def summarize_sales(rows):
    if not rows:
        raise ValueError("no rows given")
    amounts = {}
    for row in rows:
        name, _, raw = row.partition(",")
        if not raw:
            raise ValueError(f"missing amount in row: {row!r}")
        amounts[name] = float(raw)
    count = len(amounts)
    total = sum(amounts.values())
    return {
        "count": count,
        "total": total,
        "average": total / count,
        "top": max(amounts, key=amounts.get),
    }


DATA = ["Ada,120", "Grace,95", "Linus,200", "Ada,120"]

result = summarize_sales(DATA)
print("count:", result["count"])
print("total:", result["total"])
print("average:", result["average"])
print("top:", result["top"])

