from typing import NamedTuple


# A frozen, validated value object built WITHOUT a dataclass. NamedTuple gives
# the immutable named shape for free (assigning to a field raises
# AttributeError). The catch: there is no __post_init__ hook, so every
# validated instance is built through `create` -- the single boundary where a
# raw row becomes a trusted Shipment.
class Shipment(NamedTuple):
    dest: str
    weight_kg: int
    rate_per_kg: float

    @property
    def cost(self) -> float:
        return round(self.weight_kg * self.rate_per_kg, 2)

    @classmethod
    def create(cls, dest: str, weight_kg: int, rate_per_kg: float) -> "Shipment":
        """Validate the fields, THEN construct. A bad Shipment never exists.

        Rules:
          - weight_kg must be an int (reject bool) -> raise TypeError
            message: f"weight_kg must be int, got {type(weight_kg).__name__}"
          - weight_kg must be > 0 -> raise ValueError
            message: f"weight_kg must be positive, got {weight_kg}"
          - rate_per_kg must be >= 0 -> raise ValueError
            message: f"rate_per_kg must be >= 0, got {rate_per_kg}"
        """
        if isinstance(weight_kg, bool) or not isinstance(weight_kg, int):
            raise TypeError(f"weight_kg must be int, got {type(weight_kg).__name__}")
        if weight_kg <= 0:
            raise ValueError(f"weight_kg must be positive, got {weight_kg}")
        if rate_per_kg < 0:
            raise ValueError(f"rate_per_kg must be >= 0, got {rate_per_kg}")
        return cls(dest=dest, weight_kg=weight_kg, rate_per_kg=rate_per_kg)

# Fixed input data (do not change).
ROWS = [
    {"dest": "NYC", "weight_kg": 3, "rate_per_kg": 4.50},
    {"dest": "LAX", "weight_kg": 10, "rate_per_kg": 1.25},
    {"dest": "ORD", "weight_kg": 2, "rate_per_kg": 12.00},
]


def main() -> None:
    shipments = [Shipment.create(**r) for r in ROWS]
    grand_total = 0.0
    for s in shipments:
        print(f"{s.dest}: {s.weight_kg} x {s.rate_per_kg:.2f} = {s.cost:.2f}")
        grand_total += s.cost
    print(f"TOTAL: {grand_total:.2f}")

    # Prove the instance is immutable.
    try:
        shipments[0].weight_kg = 99
    except AttributeError as exc:
        print(f"frozen: {type(exc).__name__}")

    # Prove validation rejects a bad row.
    try:
        Shipment.create(dest="X", weight_kg=0, rate_per_kg=1.0)
    except ValueError as exc:
        print(f"invalid: {exc}")


if __name__ == "__main__":
    main()

