class BookingError(ValueError):
    """Raised when a booking record fails validation."""


def validate_booking(row: dict) -> dict:
    """Return a cleaned booking dict, or raise BookingError.

    Rules (raise BookingError with these exact messages):
      - required fields {"room", "nights", "guests"}; if any are missing:
            f"missing fields: {sorted(missing)}"
      - nights must be an int (accept a numeric string):
            f"nights not an integer: {row['nights']!r}"   (on failure)
      - nights must be > 0:
            f"nights must be > 0, got {nights}"
      - guests must be an int in 1..4:
            f"guests not an integer: {row['guests']!r}"    (on non-int)
            f"guests must be 1..4, got {guests}"           (out of range)
    """
    required = {"room", "nights", "guests"}
    missing = required - row.keys()
    if missing:
        raise BookingError(f"missing fields: {sorted(missing)}")
    try:
        nights = int(row["nights"])
    except (TypeError, ValueError):
        raise BookingError(f"nights not an integer: {row['nights']!r}")
    if nights <= 0:
        raise BookingError(f"nights must be > 0, got {nights}")
    try:
        guests = int(row["guests"])
    except (TypeError, ValueError):
        raise BookingError(f"guests not an integer: {row['guests']!r}")
    if not 1 <= guests <= 4:
        raise BookingError(f"guests must be 1..4, got {guests}")
    return {"room": row["room"], "nights": nights, "guests": guests}

ROWS = [
    {"room": "101", "nights": "3", "guests": "2"},
    {"room": "102", "nights": 0, "guests": 1},
    {"nights": 2, "guests": 1},
    {"room": "104", "nights": "x", "guests": 1},
    {"room": "105", "nights": 2, "guests": 9},
    {"room": "106", "nights": 1, "guests": 1},
]

clean = []
errors = []
for row in ROWS:
    try:
        clean.append(validate_booking(row))
    except BookingError as e:
        errors.append(str(e))

for rec in clean:
    print(f"OK {rec['room']} nights={rec['nights']} guests={rec['guests']}")
print(f"accepted={len(clean)} rejected={len(errors)}")
for msg in errors:
    print(f"ERR {msg}")

