from collections import deque

# An undirected social network as an adjacency list.
network = {
    "A": ["B", "C"],
    "B": ["A", "D", "E"],
    "C": ["A", "F"],
    "D": ["B"],
    "E": ["B", "F", "G"],
    "F": ["C", "E", "G"],
    "G": ["E", "F"],
}


def bfs_distances(graph, start):
    """Return {node: hops} = fewest-hops distance from start to each reachable
    node; start maps to 0. Use a FIFO queue of (node, distance): the first
    time you dequeue a node, that distance is its shortest.
    """
    if start not in graph:
        raise KeyError(f"start node {start!r} not in graph")
    dist = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for nbr in graph.get(node, []):
            if nbr not in dist:
                dist[nbr] = dist[node] + 1
                queue.append(nbr)
    return dist

distances = bfs_distances(network, "A")
for node in sorted(distances):
    print(f"{node}: {distances[node]}")

