ALLOWED_MODES = {"read", "write", "admin"}


def read_timeout(env: dict) -> int:
    """Return TIMEOUT as an int number of seconds.

    - Default to "30" when TIMEOUT is missing.
    - Raise ValueError("TIMEOUT must be an integer, got <raw>") if not an int
      (use repr of the raw string).
    - Raise ValueError("TIMEOUT out of range 1..300: <n>") if outside 1..300.
    """
    raw = env.get("TIMEOUT", "30")
    try:
        timeout = int(raw)
    except ValueError:
        raise ValueError(f"TIMEOUT must be an integer, got {raw!r}")
    if not 1 <= timeout <= 300:
        raise ValueError(f"TIMEOUT out of range 1..300: {timeout}")
    return timeout

def read_mode(env: dict) -> str:
    """Return MODE, lowercased.

    - Default to "read" when MODE is missing.
    - Raise ValueError("MODE invalid: <mode>") if not in ALLOWED_MODES
      (use repr of the offending lowercased mode).
    """
    mode = env.get("MODE", "read").lower()
    if mode not in ALLOWED_MODES:
        raise ValueError(f"MODE invalid: {mode!r}")
    return mode


SCENARIOS = [
    {},
    {"TIMEOUT": "60", "MODE": "WRITE"},
    {"TIMEOUT": "3x"},
    {"TIMEOUT": "900"},
    {"MODE": "root"},
]


def describe(env: dict) -> str:
    try:
        timeout = read_timeout(env)
        mode = read_mode(env)
    except ValueError as exc:
        return f"ERROR: {exc}"
    return f"timeout={timeout} mode={mode}"


if __name__ == "__main__":
    for env in SCENARIOS:
        print(describe(env))
